mapper.select:
WITH PARENT_MENU_INFO AS( SELECT TITLE,MENU_ID,PARENT_MENU_ID,LINK,DESCRIPTION,SEQ,UPDATE_USER FROM A1MFG.PAGE_MANAGER_MFG WHERE MODULE =#{module} and PARENT_MENU_ID IS NULL
AND MENU_ID = #{parentMenuId}
) SELECT TITLE,MENU_ID,PARENT_MENU_ID,LINK,DESCRIPTION,SEQ,UPDATE_USER FROM A1MFG.PAGE_MANAGER_MFG A WHERE MODULE =#{module} AND EXISTS( SELECT 1 FROM( SELECT MENU_ID FROM PARENT_MENU_INFO )B WHERE A.PARENT_MENU_ID = B.MENU_ID ) UNION ALL SELECT TITLE,MENU_ID,PARENT_MENU_ID,LINK,DESCRIPTION,SEQ,UPDATE_USER FROM PARENT_MENU_INFO

UPDATE A1MFG.PAGE_MANAGER_MFG
SET TITLE = #{menuName}
WHERE MENU_ID = #{menuId}

UPDATE A1MFG.PAGE_MANAGER_MFG
SET  TITLE = #{TITLE}, LINK = #{LINK}, DESCRIPTION = #{DESCRIPTION,jdbcType=VARCHAR}, SEQ = #{SEQ}, UPDATE_USER = #{UPDATE_USER}, UPDATE_TIME = SYSDATE
WHERE MENU_ID = #{MENU_ID}
